using System; using System.Collections.Generic; using UnityEngine;  [CreateAssetMenu(fileName = "QuestBox", menuName = "ReBloom/Container/QuestBox")] public class QuestBoxData : ItemContainerBase {     [Header("Quest Info")]     [SerializeField] private string questID;     [SerializeField] private bool isOneTimeOnly = true;      [Header("Preset Items (에디터에서 설정)")]     [SerializeField] private List<ItemSlotData> presetItems = new List<ItemSlotData>();      [Header("Debug Options")]     [SerializeField] private bool autoRefill = false;  // 열 때마다 다시 채워짐     [SerializeField] private bool infiniteUse = false; // 무한 사용 (테스트용)      public string QuestID => questID;     public bool IsOneTimeOnly => isOneTimeOnly && !infiniteUse;      /// <summary>     /// 프리셋 아이템으로 초기화 (게임 시작 시 또는 스폰 시)     /// </summary>     public void InitializeWithPreset()     {         Clear();          foreach (var preset in presetItems)         {             if (preset.itemID > 0 && preset.count > 0)             {                 AddItem(preset.itemID, preset.count);             }         }          Debug.Log($"[QuestBox] '{questID}' 프리셋으로 초기화됨 - {presetItems.Count}종 아이템");     }      /// <summary>     /// 아이템 회수 후 처리     /// </summary>     public void OnItemsRetrieved()     {         if (autoRefill)         {             InitializeWithPreset();             Debug.Log($"[QuestBox] '{questID}' 자동 리필됨");         }     }  #if UNITY_EDITOR     [ContextMenu("프리셋 아이템으로 채우기")]     private void Editor_FillWithPreset()     {         InitializeWithPreset();         UnityEditor.EditorUtility.SetDirty(this);     }      [ContextMenu("현재 아이템 -> 프리셋으로 저장")]     private void Editor_SaveCurrentAsPreset()     {         presetItems.Clear();         foreach (var item in Items)         {             presetItems.Add(new ItemSlotData             {                 itemID = item.itemID,                 count = item.count             });         }         UnityEditor.EditorUtility.SetDirty(this);         Debug.Log($"[QuestBox] 현재 {Items.Count}종 아이템을 프리셋으로 저장함");     } #endif }